CREATE TABLE IF NOT EXISTS app_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, group_id BIGINT NOT NULL DEFAULT 1, department VARCHAR(100), approved BOOLEAN NOT NULL DEFAULT FALSE, credit INT NOT NULL DEFAULT 100, consent BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS instrument (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, model VARCHAR(120), category VARCHAR(80), group_id BIGINT NOT NULL, department VARCHAR(100), location VARCHAR(150), price DECIMAL(12,2) NOT NULL, external_price DECIMAL(12,2) NOT NULL, asset_value DECIMAL(14,2) NOT NULL, status VARCHAR(20) NOT NULL, source VARCHAR(20) NOT NULL, open_hour INT NOT NULL DEFAULT 8, close_hour INT NOT NULL DEFAULT 18, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS qualification (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, instrument_id BIGINT NOT NULL, expires_at VARCHAR(30) NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(user_id,instrument_id));
CREATE TABLE IF NOT EXISTS reservation (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, instrument_id BIGINT NOT NULL, start_at VARCHAR(30) NOT NULL, end_at VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL, samples INT NOT NULL, project VARCHAR(500), contact VARCHAR(1000), settlement VARCHAR(1000), rate DECIMAL(12,2) NOT NULL, created_at VARCHAR(30) NOT NULL, checked_at VARCHAR(30), ended_at VARCHAR(30), reason VARCHAR(500), confirm_by VARCHAR(30), confirmed BOOLEAN NOT NULL DEFAULT TRUE, reminder_sent BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_reservation_resource ON reservation(instrument_id,status,start_at);
CREATE INDEX idx_reservation_user ON reservation(user_id,created_at);
CREATE TABLE IF NOT EXISTS slot_claim (instrument_id BIGINT NOT NULL, slot_at VARCHAR(30) NOT NULL, reservation_id BIGINT NOT NULL, PRIMARY KEY(instrument_id,slot_at));
CREATE TABLE IF NOT EXISTS bill (id BIGINT AUTO_INCREMENT PRIMARY KEY, reservation_id BIGINT NOT NULL UNIQUE, hours DECIMAL(12,6) NOT NULL, rate DECIMAL(12,2) NOT NULL, amount DECIMAL(12,2) NOT NULL, method VARCHAR(30) NOT NULL, verified BOOLEAN NOT NULL DEFAULT FALSE, adjustment DECIMAL(12,2) NOT NULL DEFAULT 0, adjustment_reason VARCHAR(500));
CREATE TABLE IF NOT EXISTS report_file (id BIGINT AUTO_INCREMENT PRIMARY KEY, reservation_id BIGINT NOT NULL, filename VARCHAR(255) NOT NULL, object_key VARCHAR(255) NOT NULL, checksum VARCHAR(64) NOT NULL, size_bytes BIGINT NOT NULL, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS violation (id BIGINT AUTO_INCREMENT PRIMARY KEY, reservation_id BIGINT NOT NULL, user_id BIGINT NOT NULL, kind VARCHAR(30) NOT NULL, points INT NOT NULL, reason VARCHAR(500), appeal VARCHAR(500), resolved BOOLEAN NOT NULL DEFAULT FALSE, restored BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(reservation_id,kind));
CREATE TABLE IF NOT EXISTS maintenance (id BIGINT AUTO_INCREMENT PRIMARY KEY, instrument_id BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, start_at VARCHAR(30) NOT NULL, end_at VARCHAR(30), closed_at VARCHAR(30));
CREATE TABLE IF NOT EXISTS notification (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, message VARCHAR(1000) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT NOT NULL, action VARCHAR(80) NOT NULL, object_id BIGINT, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS training (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, instrument_id BIGINT NOT NULL, score INT NOT NULL, created_at VARCHAR(30) NOT NULL);

